  function ic(name,size,cls,fill){
    var s=size||16;
    return '<svg class="nt-icon'+(cls?" "+cls:"")+'" width="'+s+'" height="'+s+'" viewBox="0 0 24 24" fill="'
      +(fill?"currentColor":"none")+'" stroke="currentColor" stroke-width="2" stroke-linecap="round"'
      +' stroke-linejoin="round" aria-hidden="true" focusable="false">'+(ICONS[name]||ICONS.circle||"")+"</svg>";
  }
  function attr(name,val){return val==null||val===""?"":" "+name+'="'+esc(String(val))+'"';}
  /** shadcn Badge: default, secondary, outline, success, warning, off, destructive. */
  function badge(variant,inner,cls,extra){
    return '<span class="nt-badge nt-badge--'+(variant||"default")+(cls?" "+cls:"")+'"'+(extra||"")+">"+inner+"</span>";
  }
  /** shadcn Button. sizes: default, xs, sm, lg, icon, icon-sm. */
  function btn(variant,size,inner,extra,cls){
    return '<button type="button" class="nt-btn nt-btn--'+variant+" nt-btn--size-"+size+(cls?" "+cls:"")+'"'
      +(extra||"")+">"+inner+"</button>";
  }
  /** The same Button as a link, for anything that opens a page. */
  function linkBtn(variant,size,href,inner,cls,extra){
    return '<a class="nt-btn nt-btn--'+variant+" nt-btn--size-"+size+(cls?" "+cls:"")+'" href="'+esc(href)
      +'" target="_blank" rel="noopener"'+(extra||"")+">"+inner+"</a>";
  }
  /** An outline tag whose status colour always travels with an icon and a word. */
  function tone(t,icon,inner,cls,title){
    return '<span class="nt-badge nt-badge--outline nt-commerce-tone is-'+(t||"muted")+(cls?" "+cls:"")+'"'
      +attr("title",title)+">"+(icon?ic(icon,12):"")+inner+"</span>";
  }
  /**
   * The frame every result view uses: a shadcn Card with the icon and title,
   * the provenance line under it, an optional action top right, the view's
   * rows, and an optional bordered footer.
   */
  function viewShell(o){
    return '<section class="nt-view nt-in'+(o.cls?" "+o.cls:"")+'"'+(o.extra||"")+">"
      +'<header class="nt-view-head"><h3 class="nt-view-title">'+(o.icon?ic(o.icon,16,"nt-muted"):"")+o.title+"</h3>"
      +(o.meta?'<p class="nt-view-desc">'+o.meta+"</p>":"")
      +(o.action?'<div class="nt-card-action">'+o.action+"</div>":"")
      +"</header>"+(o.body||"")
      +(o.footer?'<footer class="nt-view-foot">'+o.footer+"</footer>":"")
      +"</section>";
  }
  /** shadcn Empty: the mark (or an icon), a one-line title, one sentence. */
  function emptyState(icon,title,sentence,cls){
    return '<div class="nt-empty empty-state nt-in'+(cls?" "+cls:"")+'">'
      +(icon?ic(icon,24):mkSvg(77,44,false))
      +(title?'<div class="nt-empty-title text">'+title+"</div>":"")
      +(sentence?"<div>"+sentence+"</div>":"")+"</div>";
  }
  /** A two-to-four option switch; attr names the data attribute the handler reads. */
  function segmented(label,opts,cur,dataAttr,cls){
    return '<div class="nt-segmented'+(cls?" "+cls:"")+'" role="group"'+attr("aria-label",label)+">"
      +opts.map(function(o){
        var on=o[0]===cur;
        return '<button type="button" class="nt-segmented-opt'+(on?" is-on":"")+(o[2]?" "+o[2]:"")+'" aria-pressed="'
          +(on?"true":"false")+'" '+dataAttr+'="'+esc(o[0])+'">'+esc(o[1])+"</button>";
      }).join("")+"</div>";
  }
  /** shadcn Tabs list: a muted track, the active trigger raised on background. */
  function tabsList(tabs,cur,dataAttr){
    return '<div class="nt-tabs"><div class="nt-tabs-list" role="tablist">'+tabs.map(function(t){
      var on=t[0]===cur;
      return '<button type="button" role="tab" aria-selected="'+(on?"true":"false")+'" class="nt-tabs-trigger'
        +(on?" is-active":"")+'" '+dataAttr+'="'+esc(t[0])+'">'+esc(t[1])+"</button>";
    }).join("")+"</div></div>";
  }
  function statPill(icon,value,label){
    return '<span class="nt-stat-pill">'+(icon?ic(icon,12):"")+"<b>"+esc(String(value))+"</b>"+(label?" "+esc(label):"")+"</span>";
  }
  /** A verbatim line with its moment above it and Copy on hover. */
  function quoteBox(text,at,inner){
    return '<blockquote class="nt-quote quote-box">'+(at?'<span class="nt-quote-at quote-at">'+esc(at)+"</span>":"")
      +(inner!=null?inner:esc(text))
      +'<button type="button" class="nt-copy-btn copy-btn" data-copy="'+esc(text)+'">Copy</button></blockquote>';
  }
  /** Accordion row for the long parts of a result; open by default at most once or twice. */
  function accordion(label,body,open){
    return '<div class="nt-section section"><button type="button" class="nt-section-header section-header'+(open?" open":"")
      +'" aria-expanded="'+(open?"true":"false")+'"><span class="nt-section-label section-label">'+label+"</span>"
      +ic("chevron-down",14,"nt-chevron"+(open?" is-open":""))+"</button>"
      +'<div class="nt-section-content section-content'+(open?" open":"")+'"'+(open?"":" hidden")+">"+body+"</div></div>";
  }
  function loadBar(label){
    return '<div class="nt-loadbar nt-commerce-lbar load-bar" role="progressbar" aria-label="'+esc(label||"Loading")+'"></div>';
  }
  function progressBar(pct,label){
    var v=Math.max(0,Math.min(100,Number(pct)||0));
    return '<div class="nt-progress" role="progressbar" aria-valuenow="'+Math.round(v)+'" aria-valuemin="0" aria-valuemax="100"'
      +attr("aria-label",label)+'><div class="nt-progress-track"><i class="nt-progress-fill" style="width:'+v+'%"></i></div></div>';
  }
  var GLYPH_KEYS=["tiktok","instagram","youtube","x","twitter","douyin","xiaohongshu","bilibili","linkedin","reddit","weibo"];
  /** A network's mark in currentColor; networks with no glyph get a neutral letter tile. */
  function glyph(p,size){
    var k=String(p||"").toLowerCase(),s=size||12;
    if(GLYPH_KEYS.indexOf(k)>=0)return pSvg(k,s).replace("<svg ",'<svg class="nt-glyph" ');
    var n=pTitle(k)||"?";
    return '<span class="nt-feeds-ptile" style="width:'+s+"px;height:"+s+"px;font-size:"+Math.max(7,Math.round(s*0.62))
      +'px" role="img" aria-label="'+esc(n)+'">'+esc(n.charAt(0))+"</span>";
  }
  /** Outline pill with the network's mark and name. */
  function platTag(p,cls){
    return '<span class="nt-feeds-plat'+(cls?" "+cls:"")+'">'+glyph(p,12)+esc(pTitle(p)||"Post")+"</span>";
  }
  /** "1.2M" / "38.2k" — the design system's compact number. */
  function compact(n){
    n=Number(n)||0;
    var t=function(x){var s=x.toFixed(1);return s.slice(-2)===".0"?s.slice(0,-2):s;};
    return n>=1e6?t(n/1e6)+"M":n>=1e3?t(n/1e3)+"k":String(Math.round(n));
  }
  /** "48,210" — grouped, for counts a reader compares digit by digit. */
  function grouped(n){return (Number(n)||0).toLocaleString("en-US");}
  function plural(n,one,many){return n+" "+(n===1?one:(many||one+"s"));}

  // ─── Audio engine ───
  // Every <audio> in the view registers here so only one track is ever
  // audible: starting a sound preview pauses a playing slideshow and vice
  // versa. Elements are re-collected after each render.
  var audioReg=[];
  function registerAudio(el){
    if(!el||audioReg.indexOf(el)>-1)return;
    audioReg.push(el);
    el.addEventListener("play",function(){
      for(var i=0;i<audioReg.length;i++){
        var a=audioReg[i];
        if(a!==el&&!a.paused){try{a.pause();}catch(e){}}
      }
    });
  }
  function resetAudio(){
    for(var i=0;i<audioReg.length;i++){try{audioReg[i].pause();}catch(e){}}
    audioReg=[];
  }

  // ─── Media player controller ───
  // A transport hides the difference between the two media kinds behind one
  // interface (duration/time/seek/play/pause). The control bar is wired to
  // the transport, never to a <video> or an <audio> directly, so the same
  // handlers drive every player and the controls behave identically.
  var SLIDE_MS=3000;

  function videoTransport(box){
    var v=box.querySelector("video");
    return {
      kind:"video",
      el:v,
      // Until metadata loads the element reports NaN for its duration. With
      // preload="none" that is the whole time before the first press, and a
      // scrubber reading 0:00 of 0:00 looks like a card that has failed
      // rather than one waiting. The listing already told us how long the
      // post is, so fall back to that.
      duration:function(){
        if(isFinite(v.duration)&&v.duration>0)return v.duration;
        var d=Number(box.getAttribute("data-mp-dur"))||0;
        return d>0?d:0;
      },
      time:function(){return v.currentTime||0;},
      paused:function(){return v.paused;},
      play:function(){var r=v.play();if(r&&r.catch)r.catch(function(){});},
      pause:function(){try{v.pause();}catch(e){}},
      seek:function(t){try{v.currentTime=t;}catch(e){}},
      muted:function(m){if(m===undefined)return v.muted;v.muted=m;return m;},
      step:function(dir){this.seek(Math.max(0,this.time()+dir*5));},
      // Video paints one continuous segment.
      segment:function(){return 0;},
      audio:null,
      on:function(ev,cb){v.addEventListener(ev,cb);}
    };
  }

  function slidesTransport(box){
    var slides=box.querySelectorAll(".mp-slide");
    var audio=box.querySelector("audio");
    var total=slides.length||1;
    var idx=0,base=0,startedAt=0,running=false,seekBroken=false;
    // With a track, the track is the clock and each slide owns an equal share
    // of it. Without one, slides run on a fixed beat.
    // A track we cannot seek (a host that serves the audio without range
    // support) would strand the clock at zero while the slides moved on, so
    // we fall back to the wall clock the first time a seek refuses to take.
    function driven(){
      return !seekBroken&&!!audio&&isFinite(audio.duration)&&audio.duration>0;
    }
    function per(){return driven()?audio.duration/total:SLIDE_MS/1000;}
    function paint(){
      for(var k=0;k<total;k++){
        slides[k].classList.toggle("active",k===idx);
        slides[k].classList.toggle("is-active",k===idx);
      }
      var chip=box.querySelector(".mp-idx");
      if(chip)chip.textContent=idx+1;
    }
    var t={
      kind:"slides",
      el:box,
      total:total,
      audio:audio,
      duration:function(){return driven()?audio.duration:total*(SLIDE_MS/1000);},
      time:function(){
        if(driven())return audio.currentTime||0;
        return base+(running?(Date.now()-startedAt)/1000:0);
      },
      paused:function(){return !running;},
      play:function(){
        running=true;startedAt=Date.now();
        if(audio){var r=audio.play();if(r&&r.catch)r.catch(function(){});}
      },
      pause:function(){
        if(running)base=t.time();
        running=false;
        if(audio){try{audio.pause();}catch(e){}}
      },
      seek:function(sec){
        sec=Math.max(0,Math.min(sec,t.duration()));
        base=sec;startedAt=Date.now();
        if(audio){
          try{
            audio.currentTime=sec;
            if(sec>0.5&&Math.abs(audio.currentTime-sec)>1)seekBroken=true;
          }catch(e){seekBroken=true;}
        }
        idx=Math.max(0,Math.min(total-1,Math.floor(sec/per())));
        paint();
      },
      muted:function(m){
        if(!audio)return true;
        if(m===undefined)return audio.muted;
        audio.muted=m;return m;
      },
      // Slideshows step a whole slide at a time, not five seconds.
      step:function(dir){t.seek((idx+dir)*per());},
      segment:function(){return idx;},
      sync:function(){
        var want=Math.max(0,Math.min(total-1,Math.floor(t.time()/per())));
        if(want!==idx){idx=want;paint();}
        return t.time()>=t.duration();
      },
      on:function(ev,cb){if(audio)audio.addEventListener(ev,cb);}
    };
    paint();
    return t;
  }

  // ─── Follow-up actions ───
  // A button that spends credits must show that it will: sparkle to mark it as
  // a follow-up the model will reason over, and the price on the face. The
  // click asks the host to run the tool, and falls back to copying a ready
  // prompt where the host cannot run one from a view.
  //
  // These are the fetch prices, which is all any of these tools cost now. The
  // two that fan out to a second call are the two that are dearer than their
  // headline fetch: analyze_post and understand_social_post pay 2 for the
  // frames and 1 more for the transcript. score_draft fetches nothing, so it
  // has no badge — the || 0 below already hides it.
  var AI_PRICE={analyze_post_fast:2,write_hooks:2,create_variants:2,
    repurpose_post:2,niche_report:2,find_hook_pattern:2,analyze_post:3,
    analyze_comments:2,compare_posts:1,understand_social_post:3,analyze_creator_profile:2};

  // ChatGPT's Apps SDK does not answer the MCP Apps postMessage bridge. A
  // widget there reaches its server through window.openai.callTool, and opens
  // a link through window.openai.openExternal. This view only ever posted
  // tools/call and ui/open-link, so on ChatGPT every in-view button posted
  // into the void, waited out the 1500ms timeout and fell through to the
  // clipboard - and a sandboxed widget iframe carries no clipboard-write
  // grant either, so writeText rejected and the user was told "Copy failed"
  // while nothing had happened. Prefer the host's own API where it exists and
  // keep the bridge for the MCP Apps hosts that do answer it.
  // A tool call is not a UI event. Fetching a feed or watching a video takes
  // ten seconds and more - the discover call this view is built around
  // measures 10.3s - so the 1500ms this used to wait declared a host that was
  // running the tool correctly a failure, and showed "Copy failed" over a call
  // that then succeeded. Wait as long as the result poll does, and keep the
  // short deadline only for a host that answered neither the handshake nor
  // offers an API of its own, which is the one case where nothing is coming.
  var TOOL_CALL_BUDGET_MS=300000;
  var bridgeAlive=false;

  /** Ask the host to run a tool: onDone(result) when it does, onFail(reason)
   *  when it did and the tool refused, onFail("") only when the host cannot
   *  run it at all.
   *
   *  A refusal is a result, not a rejection, in most hosts - the tool's own
   *  isError with its reason in a text block - and taking it for success put
   *  "Sent" over a call that had failed. The two failures want different
   *  answers: a host that cannot run tools gets a prompt to paste, but a
   *  refusal (no credits, a post that would not open) would only be repeated
   *  by pasting, so it is said instead. */
  function invokeTool(tool,args,onDone,onFail){
    var settled=false;
    var fail=function(reason){ if(settled)return; settled=true; onFail(reason?String(reason).slice(0,300):""); };
    var api=window.openai;
    var native=!!(api&&typeof api.callTool==="function");
    var p=null;
    if(native){
      try{ p=api.callTool(tool,args||{}); if(p&&!p.then)p=Promise.resolve(p); }catch(e){ p=null; }
    }
    if(!p){ try{ p=send("tools/call",{name:tool,arguments:args||{}}); }catch(e2){ p=null; } }
    if(!p||!p.then){ fail(""); return; }
    p.then(function(r){
      if(settled)return;
      if(r&&r.isError){ fail(refusalOf(r)||"The tool failed without saying why."); return; }
      settled=true; onDone(r);
    },function(e){
      // Method-not-found is a host without tools/call, not a refusal.
      fail(e&&e.code!==-32601&&e.message?e.message:"");
    });
    setTimeout(function(){fail("");},(native||bridgeAlive)?TOOL_CALL_BUDGET_MS:1500);
  }

  function refusalOf(r){
    return (Array.isArray(r.content)?r.content:[])
      .map(function(c){return c&&typeof c.text==="string"?c.text:"";}).join(" ").trim();
  }

  /** Say why a card's call failed, under the row that made it. */
  function sayCallFailed(el,reason){
    var hint=el.closest(".pickbar")&&document.getElementById("pickhint");
    if(hint){hint.textContent=reason;return;}
    var row=el.closest(".ai-actions,.nt-signals-more,.nt-commerce-pactions")||el.parentNode;
    if(!row||!row.parentNode)return;
    var n=row.nextElementSibling;
    if(!n||!n.classList.contains("nt-call-error")){
      n=document.createElement("p");
      n.className="nt-call-error";
      n.setAttribute("role","status");
      row.parentNode.insertBefore(n,row.nextSibling);
    }
    n.textContent=reason;
    setTimeout(reportSize,30);
  }

  /** Show what the call came back with. A host that answers in-band hands the
   *  result straight to us; one that also pushes a tool-result notification
   *  would render the same payload again, so keep the globals bookkeeping in
   *  step and let that second pass be skipped. */
  function renderToolResult(r){
    if(!r||typeof r!=="object")return false;
    var sc=r.structuredContent;
    if(!sc||typeof sc!=="object")return false;
    lastOutRef=sc;
    try{ lastOutSig=JSON.stringify(sc); }catch(e){ lastOutSig=""; }
    toolResultReceived=true;
    render({structuredContent:sc});
    setTimeout(reportSize,50);
    return true;
  }

  /** True once the host has been asked to open the link. */
  function openHostLink(href){
    var api=window.openai;
    if(api&&typeof api.openExternal==="function"){
      try{ api.openExternal({href:href}); return true; }catch(e){}
    }
    return false;
  }

  function aiBtn(tool,label,argsJson){
    var cost=AI_PRICE[tool]||0;
    return '<button class="nt-btn nt-btn--outline nt-btn--size-sm nt-feeds-aibtn ai-btn" type="button" data-ai="'+esc(tool)+'" data-args="'+esc(argsJson)+'">'
      +'<span class="nt-ai-ico">'+ic("sparkles",14,"nt-muted")+'</span><span class="nt-lbl">'+esc(label)+"</span>"
      +(cost?badge("secondary",cost+" cr","price"):"")+"</button>";
  }

  /** Buttons offered under a single post. */
  function postAiActions(p){
    var url=p&&(p.externalUrl||p.url);
    if(!url)return "";
    var a=JSON.stringify({url:url});
    return '<div class="nt-feeds-ai is-under ai-actions"><div class="nt-feeds-ai-row">'
      +aiBtn("create_variants","Create variants",a)
      +aiBtn("write_hooks","Write hooks",a)
      +aiBtn("repurpose_post","Repurpose",a)
      +aiBtn("analyze_comments","Read comments",a)
      +"</div></div>";
  }

  function runAiTool(btn){
    var tool=btn.getAttribute("data-ai");
    var args={};
    try{args=JSON.parse(btn.getAttribute("data-args")||"{}");}catch(e){}
    var label=btn.querySelector(".nt-lbl");
    var icon=btn.querySelector(".nt-ai-ico");
    var original=label?label.textContent:"";
    var sparkle=icon?icon.innerHTML:"";
    btn.disabled=true;btn.classList.add("busy");btn.setAttribute("aria-busy","true");
    if(label)label.textContent="Working…";
    if(icon)icon.innerHTML=ic("loader-circle",14,"nt-spin");
    var restore=function(text){
      btn.classList.remove("busy");btn.removeAttribute("aria-busy");
      if(label)label.textContent=text||original;
      if(icon)icon.innerHTML=ic("check",14,"nt-muted");
      setTimeout(function(){btn.disabled=false;if(label)label.textContent=original;if(icon)icon.innerHTML=sparkle;},1600);
    };
    var settled=false;
    var fallback=function(reason){
      if(settled)return;settled=true;
      if(reason){
        restore("Failed");
        if(icon)icon.innerHTML=ic("triangle-alert",14,"nt-muted");
        sayCallFailed(btn,reason);
        return;
      }
      var ask="Run "+tool+" on "+(args.url||JSON.stringify(args));
      if(navigator.clipboard&&navigator.clipboard.writeText){
        navigator.clipboard.writeText(ask).then(function(){restore("Copied");})
          .catch(function(){restore("Try in chat");});
      }else restore("Try in chat");
    };
    invokeTool(tool,args,function(r){
      settled=true;
      restore("Sent");
      renderToolResult(r);
    },fallback);
  }

  document.addEventListener("click",function(e){
    var b=e.target.closest&&e.target.closest(".ai-btn[data-ai]");
    if(b&&!b.disabled)runAiTool(b);
  });

  // A sandboxed view cannot navigate the top-level window, so a plain anchor
  // does nothing in most hosts - the "Open on ..." buttons and the trending
  // hashtag rows were all inert. MCP Apps exposes ui/open-link for this.
  // window.open stays as the fallback for hosts that do allow it.
  document.addEventListener("click",function(e){
    var a=e.target.closest&&e.target.closest("a[href]");
    if(!a)return;
    var href=a.getAttribute("href")||"";
    if(href.indexOf("http")!==0)return;
    e.preventDefault();
    var popOut=function(){try{window.open(href,"_blank","noopener");}catch(err){}};
    if(openHostLink(href))return;
    var pr=null;
    try{pr=send("ui/open-link",{url:href});}catch(err2){}
    if(pr&&pr.then)pr.catch(popOut); else popOut();
  });

  // ─── Post selection & comparison ───
  // Comparing posts is the one action that needs more than one card, so the
  // cards themselves carry the control: a checkbox on the media, and a menu
  // that only exists once something is picked.
  var picked = [];

  /**
   * The selection bar that rises once something is picked: the count, a hint,
   * Clear, and the one action. Compare carries its price on its face, as
   * every action that spends credits does; Analyse these re-reads one post's
   * comments and says so in its own guidance.
   */
  function pickBarHtml(kind){
    var mentions=kind==="mentions";
    return '<div class="'+(mentions?"nt-signals-pickbar":"nt-feeds-pickbar")+' pickbar" id="pickbar" role="region" aria-label="Selection" hidden>'
      +'<span class="'+(mentions?"nt-signals-pickbar-n":"nt-feeds-pickbar-n")+' n"><b id="pickn">0</b> selected</span>'
      +'<span class="'+(mentions?"nt-signals-pickbar-hint":"nt-feeds-pickbar-hint")+' hint" id="pickhint">'+(mentions?"":"Pick 2 or more to compare")+"</span>"
      +'<span class="nt-feeds-pickbar-sp sp"></span>'
      +btn("ghost","sm","Clear",' id="pickclear"')
      +btn("default","sm",
        (mentions?ic("sparkles",14):ic("scales",14))
        +'<span class="nt-lbl">'+(mentions?"Analyse these":"Compare")+"</span>"
        +(mentions?"":badge("secondary",AI_PRICE.compare_posts+" cr","nt-feeds-cr")),
        ' id="pickgo"'+(mentions?"":" disabled"),"primary")
      +"</div>";
  }
  /** The go button's words, without disturbing its icon or its price. */
  function setGoLabel(go,text){
    var l=go&&go.querySelector(".nt-lbl");
    if(l)l.textContent=text;else if(go)go.textContent=text;
  }
  function goLabel(go){
    var l=go&&go.querySelector(".nt-lbl");
    return l?l.textContent:(go?go.textContent:"");
  }

  function syncPickBar(){
    var bar=document.getElementById("pickbar");
    if(!bar)return;
    bar.hidden = picked.length===0;
    var n=document.getElementById("pickn");
    if(n)n.textContent=picked.length;
    var urls=pickedUrls();
    var go=document.getElementById("pickgo");
    if(go)go.disabled = urls.length<2 || urls.length>5;
    var hint=document.getElementById("pickhint");
    if(hint){
      hint.textContent = picked.length>5 ? "Compare takes at most 5"
        : urls.length<2 ? (picked.length>=2 ? "Those are the same post" : "Pick 2 or more to compare")
        : "Ready to compare";
    }
    setTimeout(reportSize,60);
  }

  function initPicks(){
    picked=[];
    document.addEventListener("click",onPickClick);
    var clear=document.getElementById("pickclear");
    if(clear)clear.addEventListener("click",function(){
      picked=[];
      document.querySelectorAll('.mp-pick[aria-pressed="true"]').forEach(function(b){
        b.setAttribute("aria-pressed","false");
        b.classList.remove("is-on");
        var mp=b.closest(".mp"); if(mp){mp.classList.remove("picked");mp.classList.remove("is-picked");}
      });
      syncPickBar();
    });
    var go=document.getElementById("pickgo");
    if(go)go.addEventListener("click",runCompare);
    syncPickBar();
  }

  function onPickClick(e){
    var b=e.target.closest&&e.target.closest(".mp-pick[data-pick]");
    if(!b)return;
    e.stopPropagation(); // never let the tap reach the player underneath
    var id=b.getAttribute("data-pick-id");
    var i=picked.findIndex(function(x){return x.id===id;});
    var on=i<0;
    if(on)picked.push({id:id,url:b.getAttribute("data-pick")});
    else picked.splice(i,1);
    b.setAttribute("aria-pressed",on?"true":"false");
    var mp=b.closest(".mp");
    if(mp){mp.classList.toggle("picked",on);mp.classList.toggle("is-picked",on);}
    b.classList.toggle("is-on",on);
    syncPickBar();
  }

  /** Distinct URLs from the current selection — the same post picked twice
   *  is still one post to compare. */
  function pickedUrls(){
    var seen=[],out=[];
    picked.forEach(function(x){
      if(x.url&&seen.indexOf(x.url)<0){seen.push(x.url);out.push(x.url);}
    });
    return out;
  }

  /** Ask the host to run compare_posts; fall back to copying the URLs.
   *  The method is "tools/call" - MCP Apps reuses the core MCP method for
   *  tool invocation rather than defining a prefixed one of its own. This
   *  used to send a ui-prefixed name that no host answers, so every in-view
   *  action button silently timed out into the clipboard fallback. */
  function runCompare(){
    var go=document.getElementById("pickgo");
    var urls=pickedUrls().slice(0,5);
    if(!go||urls.length<2)return;
    go.disabled=true; setGoLabel(go,"Comparing…");
    var done=function(label){
      setGoLabel(go,label);
      setTimeout(function(){ setGoLabel(go,"Compare"); syncPickBar(); },1800);
    };
    // Preferred path: the host runs the tool for us.
    var settled=false;
    var fallback=function(reason){
      if(settled)return; settled=true;
      if(reason){ setGoLabel(go,"Compare"); syncPickBar(); sayCallFailed(go,reason); return; }
      // Hosts that do not support tool-calls from a view still let the user
      // paste — so hand them something ready to send.
      // Build the newline from a char code rather than an escape sequence.
      // This template is embedded both in a Rust raw string (escapes stay
      // literal) and a TS template literal (escapes are resolved), so an
      // escaped newline here becomes a real one in the TS build and breaks
      // the surrounding string literal. Same reason this comment avoids one.
      var NL=String.fromCharCode(10);
      var text="Compare these posts:"+NL+urls.join(NL);
      if(navigator.clipboard&&navigator.clipboard.writeText){
        navigator.clipboard.writeText(text).then(function(){done("Copied");})
          .catch(function(){done("Copy failed");});
      } else done("Copy failed");
    };
    invokeTool("compare_posts",{urls:urls},function(r){
      settled=true;
      done("Sent");
      renderToolResult(r);
    },fallback);
  }

  // Images cannot bubble an error, so this listens in the capture phase: any
  // <img data-fallback> that fails swaps to its fallback once. Thumbnails and
  // sound covers expire the same way videos do - a TikTok poster lasts about
  // five hours - and a dead cover is the most visible kind of broken card.
  document.addEventListener("error",function(e){
    var el=e.target;
    if(!el||el.tagName!=="IMG")return;
    var alt=el.getAttribute("data-fallback")||"";
    if(!alt||el.getAttribute("src")===alt)return;
    el.removeAttribute("data-fallback");
    el.setAttribute("src",alt);
  },true);

  // An avatar with nothing left to try hides, uncovering the initial drawn
  // underneath it. A broken-image glyph in a column of faces reads as a fault;
  // an initial reads as a person whose picture did not load.
  document.addEventListener("error",function(e){
    var el=e.target;
    if(!el||el.tagName!=="IMG"||!el.hasAttribute("data-avatar"))return;
    if(el.getAttribute("data-fallback"))return;
    el.style.display="none";
  },true);

  // A <video> poster cannot report failure: there is no error event for it, so
  // a dead cover leaves a black stage and nothing notices. TikTok cover
  // signatures expire in hours, so this is the ordinary case, not the edge -
  // measured on a two-hour-old payload whose cover already answered 403 while
  // its video still played. Probing the URL with an Image gives us the error
  // event the video will not, and the resolver hands back a fresh cover.
  function healPosters(root){
    var vids=(root||document).querySelectorAll("video[data-poster-fallback]");
    for(var i=0;i<vids.length;i++)(function(v){
      var poster=v.getAttribute("poster")||"",alt=v.getAttribute("data-poster-fallback")||"";
      v.removeAttribute("data-poster-fallback");
      if(!poster||!alt||poster===alt)return;
      var probe=new Image();
      probe.onerror=function(){v.setAttribute("poster",alt);};
      probe.src=poster;
    })(vids[i]);
  }

  // ─── Player registry ───
  // Exclusivity cannot ride on the audio elements alone: a silent slideshow
  // owns no <audio>, so it would happily keep advancing underneath a video
  // that just started. Every player registers its own stop() instead.
  var players=[];
  function registerPlayer(rec){players.push(rec);}
  function stopOtherPlayers(except){
    for(var i=0;i<players.length;i++){
      if(players[i]!==except&&players[i].isPlaying())players[i].stop(false);
    }
  }
  function stopAllPlayers(){stopOtherPlayers(null);}
  function resetPlayers(){stopAllPlayers();players=[];}

  // Mute is a session preference, not a per-card one — having to silence
  // every card in a feed one at a time is the kind of thing that makes people
  // close the tab.
  var mutePref=false;

  function initMediaPlayers(root){
    var nodes=(root||document).querySelectorAll(".mp[data-mp]");
    for(var n=0;n<nodes.length;n++)initMediaPlayer(nodes[n]);
    observeVisibility();
  }

  // ─── Pause on scroll-away ───
  // Paging to the next card in a gallery must stop the one you left, or two
  // soundtracks end up playing over each other.
  var mpObserver=null;
  function observeVisibility(){
    if(!("IntersectionObserver" in window))return;
    if(mpObserver)mpObserver.disconnect();
    mpObserver=new IntersectionObserver(function(entries){
      for(var i=0;i<entries.length;i++){
        var e=entries[i],rec=e.target.__mpRec;
        if(!rec)continue;
        if(e.intersectionRatio>=0.6){rec.wasVisible=true;warmMedia(e.target);continue;}
        // Only a card that was genuinely on screen and has scrolled away
        // stops. Without the transition check, a smooth-scroll that is still
        // settling reads as "off screen" and kills playback the instant the
        // user presses play on a partly-visible card.
        if(e.intersectionRatio<0.25&&rec.wasVisible){
          rec.wasVisible=false;
          if(rec.isPlaying())rec.stop(false);
        }
      }
    },{threshold:[0,0.25,0.6,1]});
    var nodes=document.querySelectorAll(".mp[data-mp]");
    for(var n=0;n<nodes.length;n++)mpObserver.observe(nodes[n]);
  }

  // Leaving the tab (or the host collapsing the view) must not leave audio
  // playing out of sight.
  document.addEventListener("visibilitychange",function(){
    if(document.hidden)stopAllPlayers();
  });
  window.addEventListener("pagehide",stopAllPlayers);

  // Resolver-backed video costs eight to twenty-five seconds before a URL
  // comes back. That is the provider's own latency, measured across repeated
  // calls for the same video, and they do not cache it - so nothing we do on
  // our side makes the *first* one quick. Left until the play button is
  // pressed, all of it is spent staring at a spinner, which is what "loads
  // indefinitely" was.
  //
  // A card that is genuinely on screen therefore warms itself, once. Metadata
  // only - a small range request, not the video - and it primes the resolve
  // cache so the press that follows is instant. Cards nobody scrolls to cost
  // nothing, which is the whole reason preload is "none" to begin with.
  function warmMedia(box){
    if(box.__mpWarm)return;
    var v=box.querySelector("video");
    if(!v)return;
    var src=v.getAttribute("src")||"";
    if(src.indexOf("/media/resolve")<0||v.preload!=="none")return;
    box.__mpWarm=true;
    v.preload="metadata";
    try{v.load();}catch(e){}
  }

  function initMediaPlayer(box){
    if(box.__mpInit)return;
    box.__mpInit=true;
    var t=box.getAttribute("data-mp")==="video"?videoTransport(box):slidesTransport(box);
    if(!t.el)return;
    if(t.audio)registerAudio(t.audio);
    if(t.kind==="video")registerAudio(t.el);

    var playBtn=box.querySelector(".mp-play");
    var tapBtn=box.querySelector(".mp-tap");
    var muteBtn=box.querySelector(".mp-mute");
    var seekBar=box.querySelector(".mp-seek");
    var segs=box.querySelectorAll(".mp-seg");
    var curEl=box.querySelector(".mp-cur");
    var durEl=box.querySelector(".mp-dur");
    // Driven by an interval, not requestAnimationFrame: hosts render these
    // cards in iframes that often are not compositing, where rAF never fires.
    var ticker=null;

    function paintSeek(){
      var d=t.duration(),now=t.time();
      if(segs.length<=1){
        if(segs[0])segs[0].firstChild.style.width=(d>0?Math.min(100,(now/d)*100):0)+"%";
      }else{
        var per=d/segs.length,active=t.segment();
        for(var k=0;k<segs.length;k++){
          segs[k].classList.toggle("done",k<active);
          segs[k].firstChild.style.width=
            k<active?"100%":k>active?"0":Math.max(0,Math.min(100,((now-k*per)/per)*100))+"%";
        }
      }
      if(curEl)curEl.textContent=fmtTime(now);
      if(durEl)durEl.textContent=fmtTime(d);
    }
    function setPlaying(on){
      box.classList.toggle("playing",on);
      box.classList.toggle("is-playing",on);
      if(playBtn){
        playBtn.innerHTML=mpIcon(on?"pause":"play",14);
        playBtn.setAttribute("aria-label",on?"Pause":"Play");
      }
      if(tapBtn){
        tapBtn.innerHTML="<span>"+mpIcon(on?"pause":"play",26)+"</span>";
        tapBtn.setAttribute("aria-label",on?"Pause":"Play");
      }
    }
    function applyMute(){
      t.muted(mutePref);
      if(muteBtn){
        muteBtn.innerHTML=mpIcon(mutePref?"muted":"volume",17);
        muteBtn.setAttribute("aria-label",mutePref?"Unmute":"Mute");
        muteBtn.setAttribute("aria-pressed",mutePref?"true":"false");
      }
    }
    function tick(){
      paintSeek();
      if(t.kind==="slides"&&t.sync&&!t.paused()&&t.sync())stop(true);
    }
    function start(){
      // Only one thing plays at a time, across every card in the view.
      stopOtherPlayers(rec);
      rec.wasVisible=true;
      t.play();setPlaying(true);
      clearInterval(ticker);ticker=setInterval(tick,100);
      tick();
    }
    function stop(reset){
      t.pause();setPlaying(false);
      clearInterval(ticker);ticker=null;
      if(reset)t.seek(0);
      paintSeek();
    }
    function toggle(){t.paused()?start():stop(false);}

    // Registered before any wiring so start() can reach it.
    var rec={wasVisible:false,
             isPlaying:function(){return box.classList.contains("playing");},
             stop:function(reset){stop(reset);}};
    box.__mpRec=rec;
    registerPlayer(rec);

    if(playBtn)playBtn.addEventListener("click",toggle);
    if(tapBtn)tapBtn.addEventListener("click",toggle);
    if(muteBtn)muteBtn.addEventListener("click",function(){
      mutePref=!mutePref;
      // Apply to every player, so the choice sticks across the whole feed.
      var all=document.querySelectorAll(".mp[data-mp]");
      for(var i=0;i<all.length;i++)if(all[i].__mpApplyMute)all[i].__mpApplyMute();
    });
    box.__mpApplyMute=applyMute;

    // Keyboard: the same keys people already expect from a video player.
    box.addEventListener("keydown",function(e){
      var k=e.key;
      if(k===" "||k==="Spacebar"||k==="k"){e.preventDefault();toggle();}
      else if(k==="ArrowRight"){e.preventDefault();t.step(1);paintSeek();}
      else if(k==="ArrowLeft"){e.preventDefault();t.step(-1);paintSeek();}
      else if(k==="m"||k==="M"){e.preventDefault();if(muteBtn)muteBtn.click();}
      else if(k==="Home"){e.preventDefault();t.seek(0);paintSeek();}
    });
    if(seekBar)seekBar.addEventListener("click",function(e){
      var d=t.duration();
      if(d<=0)return;
      var r=seekBar.getBoundingClientRect();
      t.seek(((e.clientX-r.left)/r.width)*d);
      paintSeek();
    });
    box.addEventListener("click",function(e){
      var nav=e.target.closest?e.target.closest(".mp-nav"):null;
      if(!nav)return;
      t.step(Number(nav.getAttribute("data-dir"))||1);
      paintSeek();
    });
    // Media the user paused from elsewhere (another player claimed the
    // audio, or the native video UI) must not leave the button lying.
    t.on("ended",function(){stop(true);});
    t.on("pause",function(){if(!box.classList.contains("playing"))return;setPlaying(false);clearInterval(ticker);});
    t.on("play",function(){if(!box.classList.contains("playing"))start();});
    t.on("loadedmetadata",paintSeek);
    // A spoken hit opens at the moment the term was said rather than at 0:00 —
    // the whole claim of that row is that the words are in the video at that
    // timecode, and making a reader scrub for them is asking them to take it
    // on trust. Once only: a seek on every metadata event would drag the
    // playhead back each time the element re-reported itself.
    var startAt=Number(box.getAttribute("data-mp-start")||0);
    if(startAt>0){
      var sought=false;
      var seekOnce=function(){
        if(sought)return;
        sought=true;
        t.seek(startAt);
        paintSeek();
      };
      t.on("loadedmetadata",seekOnce);
      // Metadata may already be in by the time this runs.
      if(t.kind==="video"&&t.el&&t.el.readyState>=1)seekOnce();
    }
    if(t.kind==="slides")t.on("timeupdate",tick);

    // Buffering and failure are states the user can see, not a frozen frame.
    var spin=box.querySelector(".mp-spin"),errBox=box.querySelector(".mp-err");
    function busy(on){if(spin)spin.hidden=!on;}
    if(t.kind==="video"){
      t.on("waiting",function(){busy(true);});
      t.on("stalled",function(){busy(true);});
      t.on("playing",function(){busy(false);});
      t.on("canplay",function(){busy(false);});
    }
    var media=t.kind==="video"?t.el:t.audio;
    if(media)media.addEventListener("error",function(){
      // One retry through the proxy before admitting defeat: the direct CDN
      // link is tried first, but some hosts refuse a cross-origin request
      // from this frame and only the proxied copy will play.
      var alt=media.getAttribute("data-fallback")||box.getAttribute("data-mp-fallback")||"";
      if(alt&&media.getAttribute("src")!==alt){
        media.removeAttribute("data-fallback");
        box.removeAttribute("data-mp-fallback");
        media.setAttribute("src",alt);
        try{media.load();}catch(e){}
        return;
      }
      busy(false);
      if(errBox)errBox.hidden=false;
      stop(false);
    });

    setPlaying(false);
    applyMute();
    paintSeek();
  }

  // ─── Sound card players ───
  function initSoundPlayers(root){
    var nodes=(root||document).querySelectorAll(".au[data-au]");
    for(var n=0;n<nodes.length;n++){
      (function(wrap){
        if(wrap.__auInit)return;
        wrap.__auInit=true;
        var audio=wrap.querySelector("audio");
        var btn=wrap.querySelector(".au-play");
        var seek=wrap.querySelector(".au-seek");
        var fill=seek?seek.firstChild:null;
        var cur=wrap.querySelector(".au-cur");
        var dur=wrap.querySelector(".au-dur");
        if(!audio||!btn)return;
        registerAudio(audio);
        btn.addEventListener("click",function(){
          if(audio.paused){var pr=audio.play();if(pr&&pr.catch)pr.catch(function(){
            wrap.setAttribute("data-error","1");
            if(cur)cur.textContent="unavailable";
          });}
          else audio.pause();
        });
        function mark(on){
          btn.innerHTML=mpIcon(on?"pause":"play",14);
          btn.setAttribute("aria-label",on?"Pause sound":"Play sound");
        }
        // A sound preview must also silence any playing card, not just other
        // previews — they are all one audio surface to the user.
        audio.addEventListener("play",function(){mark(true);stopAllPlayers();});
        audio.addEventListener("pause",function(){mark(false);});
        audio.addEventListener("ended",function(){mark(false);if(fill)fill.style.width="0";});
        audio.addEventListener("loadedmetadata",function(){
          if(dur&&isFinite(audio.duration))dur.textContent=fmtTime(audio.duration);
        });
        audio.addEventListener("timeupdate",function(){
          if(cur)cur.textContent=fmtTime(audio.currentTime);
          if(fill&&isFinite(audio.duration)&&audio.duration>0)
            fill.style.width=((audio.currentTime/audio.duration)*100)+"%";
        });
        if(seek)seek.addEventListener("click",function(e){
          if(!isFinite(audio.duration)||audio.duration<=0)return;
          var r=seek.getBoundingClientRect();
          try{audio.currentTime=((e.clientX-r.left)/r.width)*audio.duration;}catch(err){}
        });
      })(nodes[n]);
    }
  }

  // Wire every player in the freshly rendered view.
  function initPlayers(){
    resetPlayers();
    resetAudio();
    setStageMax();
    initMediaPlayers(document);
    healPosters(document);
    initSoundPlayers(document);
  }

  // ─── Stage size ───
  // Ceiling on the stage height, so a portrait post cannot run the card off
  // the screen. It is the only thing capping the stage now.
  var HARD_MAX=560;
  function availableWidth(){
    var vv=window.visualViewport;
    return (vv&&vv.width)||document.documentElement.clientWidth||window.innerWidth||0;
  }
  // The stage takes its size from the width of the frame and the aspect ratio
  // of the post. It must not take it from the frame's *height*.
  //
  // That height is provisional: the host sets a placeholder, waits for us to
  // report how tall we are, then resizes. Deriving our width from it (the CSS
  // takes .mp width from --stage-max via the ratio) made the card a function
  // of that placeholder. Measured with the same card and the same content,
  // varying only the height the host started with:
  //
  //     starts 300px -> 492x277      starts 560px -> 738x415
  //     starts 420px -> 706x397      starts 700px -> 738x415
  //
  // Deterministic, but the placeholder differs every time a virtualising host
  // unmounts a card on scroll and mounts it again - which is the "videos get
  // resized randomly when I scroll or they reload" report.
  //
  // So the cap is now fixed. Width comes from the frame, height follows from
  // the ratio, the cap only stops a portrait post running away, and we report
  // the height that produces. The host accommodates us rather than the other
  // way round, which is the only direction that terminates.
  function setStageMax(){
    document.documentElement.style.setProperty("--stage-max",HARD_MAX+"px");
  }
  // A width change is a real layout change and worth re-reporting; a height
  // change is the host answering us, and must not feed back.
  var lastWidth=availableWidth();
  function onViewportChange(){
    var w=availableWidth();
    if(w===lastWidth)return;
    lastWidth=w;
    reportSize();
  }
  if(window.visualViewport)window.visualViewport.addEventListener("resize",onViewportChange);
  window.addEventListener("orientationchange",function(){setTimeout(function(){
    lastWidth=availableWidth();reportSize();
  },120);});

  function fmtNum(n){return compact(n);}
  function pColor(p){return{tiktok:"#000",douyin:"#000",instagram:"#E4405F",youtube:"#FF0000",xiaohongshu:"#FF2442",x:"#000",twitter:"#000",bilibili:"#00A1D6",linkedin:"#0A66C2",reddit:"#FF4500",weibo:"#E6162D"}[p]||"#6B7280";}
  /** Display name for a platform key — "xiaohongshu" is not a label. */
  function pTitle(p){
    var m={tiktok:"TikTok",douyin:"Douyin",instagram:"Instagram",youtube:"YouTube",
      xiaohongshu:"Xiaohongshu",twitter:"X",x:"X",bilibili:"Bilibili",
      linkedin:"LinkedIn",reddit:"Reddit",weibo:"Weibo"};
    return m[p]||(p?String(p).charAt(0).toUpperCase()+String(p).slice(1):"");
  }
  // Brand colours are chosen against a white page. TikTok, Douyin and X are
  // pure black, so used as label text on the dark card they were invisible.
  // Keep the brand colour for fills, but lift a too-dark one toward the card
  // foreground when it has to be read as text in dark mode.
  function pColorText(p){
    var c=pColor(p);
    var dq=window.matchMedia&&window.matchMedia("(prefers-color-scheme: dark)");
    if(!dq||!dq.matches)return c;
    var h=c.replace("#","");
    if(h.length===3)h=h.charAt(0)+h.charAt(0)+h.charAt(1)+h.charAt(1)+h.charAt(2)+h.charAt(2);
    var r=parseInt(h.slice(0,2),16),g=parseInt(h.slice(2,4),16),b=parseInt(h.slice(4,6),16);
    if(isNaN(r)||isNaN(g)||isNaN(b))return c;
    if((0.2126*r+0.7152*g+0.0722*b)/255>0.38)return c;
    var t=0.66;
    return "rgb("+Math.round(r+(255-r)*t)+","+Math.round(g+(255-g)*t)+","+Math.round(b+(255-b)*t)+")";
  }
  // Official brand mark (simple-icons path) as an inline SVG that inherits
  // the current text color via fill="currentColor" — matches badge accents.
  // ─── UI icon set ───
  // Real vector icons rather than emoji: emoji render differently on every
  // OS (and some platforms colour them), so the control bar and engagement
  // rail would not look the same from one machine to the next. These inherit
  // currentColor and size, so one icon serves every context.

  // The player's own glyph names, drawn from the Lucide set the rest of the
  // view uses. Play, pause and the two engagement marks are filled, as the
  // design system draws them on a video.
  var MP_MAP={heart:["heart",1],comment:["message-square",1],share:["reply",0],eye:["eye",0],
    play:["play",1],pause:["pause",1],volume:["volume-2",0],muted:["volume-x",0],note:["music",0],
    prev:["chevron-left",0],next:["chevron-right",0],open:["external-link",0],warn:["triangle-alert",0],
    check:["check",0],sparkle:["sparkles",0]};
  function mpIcon(name,size){
    var m=MP_MAP[name]||[name,0];
    return ic(m[0],size||18,"",!!m[1]);
  }

  /**
   * One typed comment, as a row.
   *
   * Pulled out of renderMonitor so the merged feed below draws exactly the
   * same row rather than a near-copy of it: the two would drift, and the
   * whole point of merging is that a reader stops having to notice which
   * screen they are on.
   *
   * "sourced" adds the chip naming where the row came from. It is off on the
   * comment-only screen, where every row has the same answer and the chip
   * would be noise, and on in the merged feed, where it is the point.
   */
  function typedRow(m,plat,term,sourced){
    // No invented handle. "@someone" reads as an account you could go and
    // look at, and there is none — the platform withheld it, or the
    // commenter is deleted. An empty handle renders as a stated absence
    // instead of a fabricated name. (No backticks in here: this whole view
    // is one TypeScript template literal, and one would end it.)
    var hits=Number(m.hits||1),id=String(m.id||"");
    var who=m.username==null?"":String(m.username).trim();
    var pic=String(m.avatarProxyUrl||m.avatarUrl||"");
    var picAlt=String(m.avatarUrl||"");
    // A face and a platform mark, then the words — and the words lead: the
    // comment is what is being read, and who said it matters once it has
    // caught the eye.
    var face='<span class="nt-signals-face mention-av">'
      +'<span class="nt-signals-face-init mention-av-init">'+esc(initialOf(who))+"</span>"
      +(pic?'<img class="mention-av-img" data-avatar src="'+esc(pic)+'"'
          +(picAlt&&picAlt!==pic?' data-fallback="'+esc(picAlt)+'"':"")
          +' alt="" loading="lazy"/>':"")
      +'<span class="nt-signals-face-badge mention-av-badge">'+glyph(plat,9)+"</span></span>";
    return '<label class="nt-signals-row mention" data-mention-id="'+esc(id)+'">'
      +'<input type="checkbox" class="nt-pick mention-pick" data-mid="'+esc(id)+'" aria-label="Select comment"/>'
      +face
      +'<span class="nt-signals-row-body mention-body">'
      +'<span class="nt-signals-row-text mention-text">'+highlightTerm(String(m.text||""),term)+"</span>"
      +(m.note?'<span class="nt-signals-row-note mention-note">'+esc(String(m.note))+"</span>":"")
      +'<span class="nt-signals-row-meta mention-meta mention-head">'
      +(who?'<span class="nt-signals-who mention-who">@'+esc(who)+"</span>"
            :'<span class="nt-signals-who is-unknown mention-who mention-who-unknown">no handle</span>')
      +(m.postedAt?'<span class="mention-when">'+esc(friendlyTime(m.postedAt))+"</span>":"")
      +'<span class="nt-signals-stat mention-stat">'+ic("heart",12)+esc(compact(m.likes||0))+"</span>"
      +'<span class="nt-signals-stat mention-stat">'+ic("message-square",12)+esc(compact(m.replies||0))+"</span>"
      +(hits>1?'<span class="nt-signals-hits mention-hits" title="names it '+hits+' times">×'+hits+"</span>":"")
      +labelChips(m)
      +(sourced?badge("outline","comment","chip chip-cat"):"")
      +"</span></span></label>";
  }

  /**
   * A spoken hit's own stage: the post's video, opened at the line.
   *
   * The design's case for this is that a quote lifted out of a transcript is
   * an assertion, and the video is the evidence for it — putting the two a
   * click apart is what makes a reader either trust the row or ignore it. So
   * the top spoken hit in a group gets a real player seeked to its own
   * timecode, and the rows underneath stay the compact feed.
   *
   * Only when there is something to play and somewhere to start: a hit whose
   * post carries no video, or whose track had no timings, falls back to the
   * thumbnail the row already shows rather than a black rectangle.
   */

  /**
   * The same video, opened at the moment the term was said.
   *
   * Only YouTube is given a timestamp: it reads ?t= (and &t=) on a watch URL
   * and lands there. TikTok has no public deep link into a moment, so its row
   * shows the timecode and the link opens the post — a ?t= it ignores would
   * promise a jump that never happens.
   */
  function linkAtMoment(url,plat,startMs){
    var u=String(url||"");
    if(!u||plat!=="youtube"||typeof startMs!=="number")return u;
    var secs=Math.max(0,Math.floor(startMs/1000));
    // Before the fragment, not after it: everything past a # is the
    // fragment, so a t= appended there is part of that string and never
    // reaches the query the player reads.
    var hash=u.indexOf("#"),frag=hash>=0?u.slice(hash):"";
    if(hash>=0)u=u.slice(0,hash);
    return u+(u.indexOf("?")>=0?"&":"?")+"t="+secs+"s"+frag;
  }

  /**
   * One spoken line, as the same row.
   *
   * Where a comment carries a face and its likes, a spoken line carries the
   * video's thumbnail and the reach of the video it was said in — the
   * commenter is the creator, and there is no separate account behind the
   * words. The note is not decoration: a line lifted off a caption track is
   * a different kind of evidence from a comment somebody typed, and a reader
   * scanning a merged feed has to be able to tell without checking.
   *
   * The timecode is the caption track's own, carried through from the cue the
   * match landed in — not estimated from how far through the transcript it
   * sits, which would be wrong by however long the speaker paused. A track
   * with no timings (the speech-to-text fallback, on the platforms that
   * publish no captions) yields no timecode rather than a plausible wrong
   * one, and the row simply reads "spoken".
   */
  function spokenRow(hit,ex,i,term){
    var post=hit.post||{},plat=String(post.platform||"");
    var id=spokenId(hit,ex,i);
    var thumb=String(post.thumbnailUrl||post.thumbnailProxyUrl||"");
    var thumbFb=String((post.thumbnailUrl&&(post.thumbnailFallbackUrl||post.thumbnailProxyUrl))||"");
    var text=String(ex.text||"");
    var at=ex.timecode?String(ex.timecode):"";
    // The commenter is the creator here, so the face is the video's own
    // thumbnail rather than an avatar, with a microphone when there is none.
    var face='<span class="nt-signals-face is-square'+(thumb?" sm-thumb-badged":"")+'">'
      +'<span class="nt-signals-face-init">'+ic("mic",14)+"</span>"
      +(thumb?'<img class="sm-thumb-img" data-avatar src="'+esc(thumb)+'"'
        +(thumbFb&&thumbFb!==thumb?' data-fallback="'+esc(thumbFb)+'"':"")+' alt="" loading="lazy"/>':"")
      +'<span class="nt-signals-face-badge mention-av-badge">'+glyph(plat,9)+"</span></span>";
    return '<label class="nt-signals-row mention" data-mention-id="'+esc(id)+'">'
      +'<input type="checkbox" class="nt-pick mention-pick" data-mid="'+esc(id)+'" aria-label="Select spoken line"/>'
      +face
      +'<span class="nt-signals-row-body mention-body">'
      +'<span class="nt-signals-row-text mention-text">'+highlightTerm(text,term)+"</span>"
      +'<span class="nt-signals-row-note mention-note">From the caption track, not inferred. The words are the '
      +"creator’s, in the video"+(at?", at "+esc(at):"")+".</span>"
      +'<span class="nt-signals-row-meta mention-meta mention-head">'
      +'<span class="nt-signals-who mention-who">spoken'+(at?" · "+esc(at):"")+"</span>"
      +(post.postedAt?'<span class="mention-when">'+esc(friendlyTime(post.postedAt))+"</span>":"")
      +(post.views?'<span class="nt-signals-stat mention-stat">'+ic("eye",12)+esc(compact(post.views))+"</span>":"")
      +badge("outline","transcript","chip chip-cat")
      +"</span></span></label>";
  }

  /**
   * The monitoring screen, kept in a variable so filtering and sorting redraw
   * without another paid call. A sandboxed view cannot re-query; anything the
   * user narrows has to be narrowed from what is already here.
   */
  var monitorState=null;
  var monitorTerm="";

  /**
   * search_spoken_mentions's own state, kept separately from monitorState
   * rather than shoehorned into it: the unit here is a video with excerpts,
   * not a comment, and the two payloads share only the idiom, not the shape.
   */
  var spokenState=null;

  /**
   * Sentiment and category, when something has classified the comment.
   *
   * These are absent on a brand sweep and present on a show_comment_review,
   * because the sweep has no basis for them — nothing in the payload says
   * whether a comment is angry, and colouring it from a keyword guess would be
   * confidently wrong about the exact thing being scanned for. When a model
   * has actually read the words, the label is worth something, so it is drawn.
   */
  function labelChips(m){
    var out="";
    var s=String(m.sentiment||"");
    if(s)out+=badge(s==="positive"?"success":s==="negative"?"warning":"outline",esc(s),"chip chip-"+esc(s));
    var c=String(m.category||"");
    if(c)out+=badge("secondary",esc(c.split("_").join(" ")),"chip chip-cat");
    return out;
  }

  /** The counts a review carries, as the same filter chips the sweep uses. */

  /** Identifies a group across a redraw. The permalink is the stable part. */
  function groupKey(t){
    var post=t.post||{};
    return String(post.externalUrl||(post.platform||"")+":"+(post.title||""));
  }
  /** The group a key names, or null if the page has moved on. */
  function groupByKey(k){
    var found=null;
    (monitorState?monitorState.threads:[]).forEach(function(t){
      if(!found&&groupKey(t)===k)found=t;
    });
    return found;
  }

  /**
   * The comments "select all" means, for one group.
   *
   * Collapsing and filtering look alike — both leave rows off the screen — but
   * they mean opposite things. A collapsed comment is hidden to save space and
   * the reader still meant it; a filtered-out one they deliberately excluded.
   * So this ignores the fold and honours the filter.
   */
  function selectableMentions(t){
    var all=t.mentions||[];
    if(!monitorState||!monitorState.filter||!monitorState.byCategory)return all;
    var want=monitorState.filter;
    return all.filter(function(m){return String(m.category||"")===want;});
  }

  /** How many comments a group shows before it asks. */
  var GROUP_PEEK=4;
  /** Groups the reader has opened, by post URL, kept across a filter or sort. */
  var expandedGroups={};
  // Posters the reader has asked to play, keyed like expandedGroups.
  var expandedMedia={};

  /** Reach of the post a comment sits under — how many people saw it. */
  function postReach(post){
    var bits=[];
    if(post.views)bits.push(fmtNum(post.views)+" views");
    if(post.likes)bits.push(fmtNum(post.likes)+" likes");
    if(post.comments)bits.push(fmtNum(post.comments)+" comments");
    return bits.slice(0,2).join(" · ");
  }

  /** Newest comment in a group, for the "recent first" ordering. */
  function groupNewest(t){
    var best=0;
    (t.mentions||[]).forEach(function(m){
      var d=new Date(String(m.postedAt||""));
      if(!isNaN(d.getTime())&&d.getTime()>best)best=d.getTime();
    });
    return best;
  }

  function renderMonitor(){
    var app=document.getElementById("app");
    if(!app||!monitorState)return;
    var st=monitorState;
    var keep=st.threads.filter(function(t){
      // A post with no matching comment earns its space only when the post
      // itself names the term; otherwise it is a card that says nothing.
      return Number(t.mentionCount||0)>0||!!t.postIsAboutTerm;
    });
    // Which platforms have something on screen — not the same as which have a
    // comment. A post that names the term with no matching replies still shows.
    var onScreen={};
    keep.forEach(function(t){onScreen[String((t.post||{}).platform||"")]=true;});
    // A brand sweep filters by network, because it spans many. A review is one
    // post, so the network is a constant and the useful cut is the label the
    // model put on each comment — which means filtering inside a group rather
    // than dropping whole ones.
    var shown=!st.filter?keep
      :st.byCategory
        ?keep.map(function(t){
          var kept=(t.mentions||[]).filter(function(m){return String(m.category||"")===st.filter;});
          return kept.length?{post:t.post,postIsAboutTerm:t.postIsAboutTerm,
            mentionCount:kept.length,mentions:kept}:null;
        }).filter(Boolean)
        :keep.filter(function(t){
          return String((t.post||{}).platform||"")===st.filter;
        });
    if(st.sort==="new"){
      shown=shown.slice().sort(function(a,b){return groupNewest(b)-groupNewest(a);});
    }

    var chips="";
    if(st.byCategory){
      var counts=st.byCategory;
      var keys=Object.keys(counts).sort(function(a,b){return counts[b]-counts[a];});
      if(keys.length){
        chips=filterChip("data-filter","","All",st.total,!st.filter,false,"")
          +keys.map(function(k){
            return filterChip("data-filter",k,k.split("_").join(" "),counts[k],st.filter===k,!Number(counts[k]),"");
          }).join("");
      }
    }else{
      var order=Object.keys(st.counts).sort(function(a,b){return (st.counts[b]||0)-(st.counts[a]||0);});
      // A platform that returned nothing still gets a chip — "we looked there
      // and it was quiet" is an answer — but it is not a filter, because
      // filtering to it is a dead end.
      if(order.length){
        chips=filterChip("data-filter","","All",st.total,!st.filter,false,"")
          +order.map(function(k){
            return filterChip("data-filter",k,pTitle(k),Number(st.counts[k]||0),st.filter===k,!onScreen[k],k);
          }).join("");
      }
    }
    var live=Object.keys(st.counts).filter(function(k){return Number(st.counts[k]||0)>0;});

    var head=mentionHead({
      icon:st.byCategory?"message-square":"at-sign",
      title:(st.byCategory?"Comment review — ":"Mentions of ")+"<b>"+esc(st.term)+"</b>",
      total:esc(plural(st.total,"comment"))
        +(!st.byCategory&&live.length?" across "+esc(plural(live.length,"network")):""),
      since:sinceBadge(st),
      switcher:segmented("Sort",[["loud","Loudest","msort-btn"],["new","Newest","msort-btn"]],st.sort,"data-sort"),
      summary:st.summary?esc(st.summary):"",
      chips:chips,
      notes:st.unavailable.length
        ?mentionNote("circle-alert","Could not reach "
          +st.unavailable.map(function(u){return esc(pTitle(u&&u.platform||u||"?"));}).join(", ")
          +" — those networks may have more.","mention-down"):""
    });

    if(!shown.length){
      app.innerHTML=mentionsShell(head,'<div class="nt-signals-pad">'
        +emptyState("search",st.filter?"Nothing from "+esc(st.byCategory?st.filter.split("_").join(" "):pTitle(st.filter)):"Nobody has mentioned that yet","")+"</div>");
      setTimeout(reportSize,50);
      return;
    }

    var groups=shown.map(function(t){
      var post=t.post||{},plat=String(post.platform||"");
      var n=Number(t.mentionCount||0);
      var all=t.mentions||[];
      // A coordinated burst — seven near-identical fan posts under one Weibo
      // thread is a real shape in this data — should read as one loud thing,
      // not push everything else off the screen. Nothing is dropped: the rest
      // are one click away, and the click costs nothing.
      var key=groupKey(t);
      var open=expandedGroups[key],cut=open?all.length:Math.min(all.length,GROUP_PEEK);
      var rows=all.slice(0,cut).map(function(m){return typedRow(m,plat,st.term,false);}).join("");
      return mentionGroup({post:post,key:key,
        about:t.postIsAboutTerm?badge("secondary","about "+esc(st.term),"mgroup-about"):"",
        title:esc(String(post.title||post.caption||"").slice(0,140)),
        link:String(post.externalUrl||""),
        // A post can name the term while none of its comments do; there is
        // nothing to select there, so do not offer to select it.
        selectAttr:n?'data-group-all="'+esc(key)+'"':"",selectCount:n,
        rows:n?'<div class="nt-signals-rows mentions">'+rows
             +(all.length>GROUP_PEEK?restButton(key,open,all.length-cut):"")+"</div>"
           :'<div class="nt-signals-none mgroup-none">The post names '+esc(st.term)+", but none of its comments do.</div>"});
    }).join("");

    var more=st.hasMore&&!st.filter
      ? '<div class="nt-signals-more">'+btn("outline","sm","Load more mentions",' data-next-offset="'+esc(String(st.nextOffset))
        +'" data-term="'+esc(st.term)+'"',"mention-more")+"</div>"
      : "";
    app.innerHTML=mentionsShell(head,'<div class="nt-signals-groups mgroups">'+groups+"</div>",more+pickBarHtml("mentions"));
    initMentionPicks();
    // Selections survive a filter or sort: narrowing the view is not unpicking.
    applyMentionPicks();
    setTimeout(reportSize,60);
  }

  // Filter and sort redraw from memory rather than re-querying — the view has
  // no way to call the tool again for free, and the user did not ask to spend.
  document.addEventListener("click",function(e){
    var mp0=e.target.closest&&e.target.closest("[data-mplay]");
    if(feedIsMerged()&&!mp0)return;
    var chip=e.target.closest&&e.target.closest(".mchip[data-filter]");
    if(chip&&monitorState){
      monitorState.filter=chip.getAttribute("data-filter")||"";
      renderMonitor();
      return;
    }
    var sort=e.target.closest&&e.target.closest(".msort-btn");
    if(sort&&monitorState){
      monitorState.sort=sort.getAttribute("data-sort")||"loud";
      renderMonitor();
      return;
    }
    var rest=e.target.closest&&e.target.closest("[data-expand]");
    if(rest&&monitorState){
      var k=rest.getAttribute("data-expand")||"";
      expandedGroups[k]=!expandedGroups[k];
      renderMentions();
      return;
    }
    var mplay=e.target.closest&&e.target.closest("[data-mplay]");
    if(mplay&&(monitorState||spokenState)){
      var mkey=mplay.getAttribute("data-mplay")||"";
      if(mkey&&mplay.className.indexOf("is-playable")>=0){
        expandedMedia[mkey]=true;
        renderMentions();
        // renderMentions draws outside the top-level render, so anything it
        // just wrote has nothing bound to it. initPlayers resets first, so
        // calling it again here is safe.
        initPlayers();
        var v=document.querySelector(".mgroup-stage video");
        if(v){registerAudio(v);stopAllPlayers();}
      }
      return;
    }
    var all=e.target.closest&&e.target.closest("[data-group-all]");
    if(all&&monitorState){
      // Over the group's comments, not its rendered rows: a collapsed comment
      // is still one the reader asked for when they said "all".
      var t=groupByKey(all.getAttribute("data-group-all")||"");
      if(!t)return;
      var ids=selectableMentions(t).map(function(m){return String(m.id||"");}).filter(Boolean);
      var turnOn=ids.some(function(id){return pickedMentions.indexOf(id)<0;});
      ids.forEach(function(id){
        var i=pickedMentions.indexOf(id);
        if(turnOn&&i<0)pickedMentions.push(id);
        if(!turnOn&&i>=0)pickedMentions.splice(i,1);
      });
      applyMentionPicks();
    }
  });

  /**
   * search_spoken_mentions — the mirror of the brand-monitoring screen above,
   * for a spoken line rather than a typed comment.
   *
   * The excerpt is the star: it is a direct quote of what was actually said,
   * with the term marked inside it exactly the way a comment's term match is
   * marked above (highlightTerm, reused verbatim — same rose highlight, same
   * escaping discipline, because the text underneath is still a stranger's
   * words and must not be trusted with markup of its own). Each hit is one
   * video, identified the way a card identifies one everywhere else in this
   * template: platform, author, a thumbnail, its reach. And because the
   * expensive part of this tool is deciding how far to look rather than what
   * it found, the funnel — candidates seen, transcribed, captioned, matched —
   * is drawn every time, including on an empty result, so a person can tell
   * "nothing happened" apart from "nothing was said".
   */
  function renderSpoken(){
    var app=document.getElementById("app");
    if(!app||!spokenState)return;
    var st=spokenState;

    // Tallied from the hits actually on screen, not asked for a second
    // field the backend does not send — the same principle as onScreen in
    // renderMonitor.
    var counts={};
    st.hits.forEach(function(h){
      var p=String((h.post||{}).platform||"");
      counts[p]=(counts[p]||0)+1;
    });
    var order=st.platforms.slice().sort(function(a,b){return (counts[b]||0)-(counts[a]||0);});
    var chips=order.length>1?filterChip("data-splatform","","All",st.hits.length,!st.filter,false,"")
      +order.map(function(k){
        var n=Number(counts[k]||0);
        return filterChip("data-splatform",k,pTitle(k),n,st.filter===k,!n,k);
      }).join(""):"";

    var shown=!st.filter?st.hits.slice()
      :st.hits.filter(function(h){return String((h.post||{}).platform||"")===st.filter;});
    shown=shown.slice().sort(function(a,b){
      return st.sort==="views"
        ? (Number((b.post||{}).views)||0)-(Number((a.post||{}).views)||0)
        : (Number(b.matchCount)||0)-(Number(a.matchCount)||0)
          || (Number((b.post||{}).views)||0)-(Number((a.post||{}).views)||0);
    });

    // The funnel is drawn every time, including on an empty result, so a
    // person can tell "nothing happened" apart from "nothing was said".
    var funnel='<div class="nt-signals-funnel">'
      +statPill("eye",st.considered,"considered")+statPill("file-text",st.transcribed,"transcribed")
      +statPill("mic",st.transcriptsAvailable,"had captions")+statPill("check",st.matched,"matched")+"</div>";
    var head=mentionHead({icon:"mic",
      title:"Spoken mentions of <b>"+esc(st.term)+"</b>",
      total:esc(plural(st.matched,"video"))+" say it out loud"
        +(st.platforms.length?" · "+esc(st.platforms.map(pTitle).join(" + ")):""),
      switcher:segmented("Sort",[["loud","Loudest","msort-btn"],["views","Most viewed","msort-btn"]],st.sort,"data-ssort"),
      funnel:funnel,chips:chips,
      notes:st.ceilingReached?mentionNote("triangle-alert","Only the "+esc(String(st.maxTranscripts))+" most-viewed candidates were "
        +"transcribed — "+esc(String(Math.max(0,st.considered-st.maxTranscripts)))+" more were found and never checked. "
        +"Raise maxTranscripts to look further.","mention-down"):""});

    if(!shown.length){
      var emptyText=st.filter?"Nothing from "+esc(pTitle(st.filter))
        :st.transcribed===0?"No candidate posts were found to transcribe"
        :"Nobody said it on camera in what was checked";
      app.innerHTML=mentionsShell(head,'<div class="nt-signals-pad">'+emptyState("mic",emptyText,"")+"</div>");
      setTimeout(reportSize,50);
      return;
    }

    var groups=shown.map(function(h){
      var post=h.post||{},plat=String(post.platform||"");
      var handle=String(post.creatorHandle||post.author||post.username||"").replace(/^@/,"");
      var count=Number(h.matchCount||0);
      var moment=firstMoment([h]);
      var exs=h.excerpts||[];
      var moreMatches=count-exs.length;
      var quotes=exs.map(function(ex){
        var text=String(ex.text||"");
        return '<blockquote class="nt-signals-quote quote-box">'
          +(ex.timecode?'<span class="nt-signals-quote-at quote-at">'+ic("clock",12)+esc(String(ex.timecode))+"</span>":"")
          +'<span class="nt-signals-quote-text mention-text">'+highlightTerm(text,st.term)+"</span>"
          +btn("ghost","icon-sm",ic("copy",14),' aria-label="Copy quote" data-copy="'+esc(text)+'"',"nt-signals-quote-copy copy-btn")
          +"</blockquote>";
      }).join("");
      var meta=(h.wordCount?badge("outline",esc(grouped(h.wordCount))+" words"):"")
        +(h.language?badge("outline",esc(String(h.language))):"")
        +(h.autoGenerated?badge("outline","auto-generated"):"");
      return mentionGroup({post:post,key:groupKey(h),startMs:moment&&moment.startMs,
        title:(handle?'<span class="nt-muted">@'+esc(handle)+" — </span>":"")+esc(String(post.title||post.caption||"").slice(0,160)),
        link:linkAtMoment(String(post.externalUrl||""),plat,moment&&moment.startMs),
        linkLabel:moment?"Open at "+moment.timecode:"Open",
        extra:(count?'<span class="nt-signals-hits mention-hits" title="names it '+esc(String(count))+' times">×'+esc(String(count))+"</span>":"")+meta,
        rows:'<div class="nt-signals-quotes">'+quotes
          +(moreMatches>0?'<div class="nt-signals-faint">+'+esc(plural(moreMatches,"more mention"))+" later in this video, not shown</div>":"")
          +"</div>"});
    }).join("");

    app.innerHTML=mentionsShell(head,'<div class="nt-signals-groups mgroups">'+groups+"</div>",
      st.unavailableCount?'<footer class="nt-view-foot">'+esc(plural(st.unavailableCount,"candidate"))+" could not be reached or transcribed.</footer>":"");
    setTimeout(reportSize,60);
  }

  // Same reasoning as renderMonitor's own delegate: redraw from memory, never
  // re-fetch. Distinct data attributes (data-splatform/data-ssort rather than
  // data-filter/data-sort) so this cannot be confused with the monitor's own
  // clicks even though both reuse the same .mchip/.msort-btn look.
  document.addEventListener("click",function(e){
    var chip=e.target.closest&&e.target.closest("[data-splatform]");
    if(chip&&spokenState){
      if(chip.hasAttribute("disabled"))return;
      spokenState.filter=chip.getAttribute("data-splatform")||"";
      renderSpoken();
      return;
    }
    var sort=e.target.closest&&e.target.closest("[data-ssort]");
    if(sort&&spokenState){
      spokenState.sort=sort.getAttribute("data-ssort")||"loud";
      renderSpoken();
      return;
    }
  });

  // ─── One sweep, both kinds of mention ───
  // search_mentions reads what people typed; search_spoken_mentions reads
  // what was said out loud in the video. They used to draw through two
  // separate surfaces, and a person monitoring a name does not care which of
  // the two found it. When both have answered about the same term they merge
  // here: one feed, one term, one selection, with the source stated per row.
  //
  // Neither state is thrown away to build this — the merge is a view over
  // both, so switching the source back redraws from memory and never
  // re-queries. Only the transcript half is metered per hit, because only it
  // costs per transcript, which is why the spoken row says so.
  var feedSource="both";
  /** Which sweep answered last, so a lone result still draws its own screen. */
  var lastMentionKind="";

  /** True once both sweeps have answered about the same name. */
  function feedIsMerged(){
    return !!(monitorState&&spokenState&&monitorState.term===spokenState.term
      &&!monitorState.byCategory);
  }

  /** The id a spoken excerpt is selected by, namespaced so it cannot collide
      with a comment id — those are the platform's own. */
  function spokenId(hit,ex,i){
    return "spoken:"+String(hit.postId||groupKey(hit))+":"+String(ex.occurrence||i+1);
  }

  /** Every spoken excerpt on screen, flattened, for selection and hand-off. */
  function spokenExcerpts(){
    var out=[];
    if(!spokenState)return out;
    spokenState.hits.forEach(function(h){
      (h.excerpts||[]).forEach(function(ex,i){
        out.push({id:spokenId(h,ex,i),text:String(ex.text||""),hit:h});
      });
    });
    return out;
  }

  /** The one network the reader has narrowed to, or "" for all of them. */
  var feedFilter="";

  /** Both sweeps' findings, keyed by the post they are about. */
  function mergedGroups(){
    var order=[],by={};
    function slot(post){
      var k=groupKey({post:post});
      if(!by[k]){
        by[k]={key:k,post:post||{},typed:[],spoken:[],typedCount:0,postIsAboutTerm:false};
        order.push(k);
      }
      return by[k];
    }
    if(feedSource!=="spoken"&&monitorState){
      monitorState.threads.forEach(function(t){
        // Same rule the comment-only screen uses: a post with no matching
        // comment earns its space only when the post itself names the term.
        if(!(Number(t.mentionCount||0)>0||t.postIsAboutTerm))return;
        var g=slot(t.post||{});
        g.typed=g.typed.concat(t.mentions||[]);
        g.typedCount+=Number(t.mentionCount||0);
        if(t.postIsAboutTerm)g.postIsAboutTerm=true;
      });
    }
    if(feedSource!=="typed"&&spokenState){
      spokenState.hits.forEach(function(h){slot(h.post||{}).spoken.push(h);});
    }
    var groups=order.map(function(k){return by[k];});
    if(feedFilter){
      groups=groups.filter(function(g){return String(g.post.platform||"")===feedFilter;});
    }
    // Spoken first: it is the scarcer signal and the reason the two were
    // merged at all — a name said on camera to 96K viewers is not the same
    // event as a comment under the video, and burying it under whichever
    // post happened to collect more replies loses that.
    return groups.sort(function(a,b){
      return (b.spoken.length?1:0)-(a.spoken.length?1:0)
        || (b.spoken.length+b.typedCount)-(a.spoken.length+a.typedCount);
    });
  }

  /** Platform counts across both sweeps, for the shared chip row. */
  function feedCounts(){
    var counts={};
    function add(k,n){k=String(k||"");if(k)counts[k]=(counts[k]||0)+n;}
    if(feedSource!=="spoken"&&monitorState){
      Object.keys(monitorState.counts||{}).forEach(function(k){
        add(k,Number(monitorState.counts[k]||0));
      });
    }
    if(feedSource!=="typed"&&spokenState){
      spokenState.hits.forEach(function(h){add((h.post||{}).platform,1);});
    }
    return counts;
  }

  function renderFeed(){
    var app=document.getElementById("app");
    if(!app||!feedIsMerged())return;
    var term=monitorState.term;
    var typedTotal=Number(monitorState.total||0);
    var spokenTotal=Number(spokenState.matched||0);
    var groups=mergedGroups();

    var counts=feedCounts();
    var order=Object.keys(counts).sort(function(a,b){return counts[b]-counts[a];});
    var allN=feedSource==="typed"?typedTotal:feedSource==="spoken"?spokenTotal:typedTotal+spokenTotal;
    var chips=order.length>1?filterChip("data-feed-filter","","All",allN,!feedFilter,false,"")
      +order.map(function(k){
        return filterChip("data-feed-filter",k,pTitle(k),counts[k],feedFilter===k,!counts[k],k);
      }).join(""):"";

    var total=feedSource==="typed"?esc(String(typedTotal))+" typed"
      :feedSource==="spoken"?esc(String(spokenTotal))+" spoken"
      :esc(String(typedTotal))+" typed · "+esc(String(spokenTotal))+" spoken";

    // The two prices are two different things, and rolling them into one
    // number would hide the only one an argument moves. A comment sweep is
    // priced per network and always runs; a transcript is priced per video
    // and only runs on the candidates that survive the cut.
    var summary=esc(String(spokenState.considered))+" candidate"
      +(spokenState.considered===1?"":"s")+" considered, "
      +esc(String(spokenState.transcribed))+" transcribed, "
      +esc(String(spokenState.transcriptsAvailable))+" had captions, "
      +esc(String(spokenState.matched))+" matched.";

    var notes="";
    if(spokenState.ceilingReached&&feedSource!=="typed")
      notes+=mentionNote("triangle-alert","Only the "+esc(String(spokenState.maxTranscripts))
        +" most-viewed candidates were transcribed — "
        +esc(String(Math.max(0,spokenState.considered-spokenState.maxTranscripts)))+" more were found and never checked.","mention-down");
    if(monitorState.unavailable.length&&feedSource!=="spoken")
      notes+=mentionNote("circle-alert","Could not reach "
        +monitorState.unavailable.map(function(u){return esc(pTitle(u&&u.platform||u||"?"));}).join(", ")
        +" — those networks may have more.","mention-down");

    var head=mentionHead({icon:"at-sign",
      title:"Mentions of <b>"+esc(term)+"</b>",
      total:total,since:sinceBadge(monitorState),
      switcher:segmented("Source",[["both","Both","msort-btn"],["typed","Typed","msort-btn"],["spoken","Spoken","msort-btn"]],feedSource,"data-source"),
      summary:summary,chips:chips,notes:notes});

    if(!groups.length){
      // "Nothing was said" and "nothing happened" are different answers, so
      // the funnel is drawn even on an empty one.
      var text=feedFilter?"Nothing from "+esc(pTitle(feedFilter))
        :feedSource==="spoken"?"Nobody said it out loud"
        :"Nobody has mentioned that yet";
      var why=feedSource==="spoken"&&typedTotal>0
        ? summary+" The "+esc(String(typedTotal))+" typed mention"+(typedTotal===1?" is":"s are")
          +" still there — switch the source back to <b>Typed</b>."
        : "";
      app.innerHTML=mentionsShell(head,'<div class="nt-signals-pad">'+emptyState(feedSource==="spoken"?"mic":"search",text,why)+"</div>");
      setTimeout(reportSize,50);
      return;
    }

    var html=groups.map(function(g){
      var post=g.post,plat=String(post.platform||"");
      var open=expandedGroups[g.key];
      var cut=open?g.typed.length:Math.min(g.typed.length,GROUP_PEEK);
      // The first spoken excerpt is what the group's "open at" link and its
      // poster jump to — the same moment its top row shows.
      var moment=firstMoment(g.spoken);
      var rows=g.spoken.map(function(h){
        return (h.excerpts||[]).map(function(ex,i){return spokenRow(h,ex,i,term);}).join("");
      }).join("")
        +g.typed.slice(0,cut).map(function(m){return typedRow(m,plat,term,true);}).join("");
      var selectable=g.spoken.reduce(function(n,h){return n+(h.excerpts||[]).length;},0)+g.typed.length;
      // The spoken hit's own copy of the post is the one that carries the
      // stream; the comment sweep's copy of the same post often does not.
      return mentionGroup({post:post,key:g.key,startMs:moment&&moment.startMs,
        mediaPost:g.spoken.length?resolvePostMedia(g.spoken[0].post||{}).video?g.spoken[0].post:post:post,
        about:g.spoken.length?badge("secondary",ic("mic",12)+"said out loud","mgroup-about")
          :g.postIsAboutTerm?badge("secondary","about "+esc(term),"mgroup-about"):"",
        title:esc(String(post.title||post.caption||"").slice(0,140)),
        link:linkAtMoment(String(post.externalUrl||""),plat,moment&&moment.startMs),
        linkLabel:moment?"Open at "+moment.timecode:"Open",
        selectAttr:selectable?'data-feed-all="'+esc(g.key)+'"':"",selectCount:selectable,
        rows:rows?'<div class="nt-signals-rows mentions">'+rows
            +(g.typed.length>GROUP_PEEK?restButton(g.key,open,g.typed.length-cut):"")+"</div>"
          :'<div class="nt-signals-none mgroup-none">The post names '+esc(term)+", but none of its comments do.</div>"});
    }).join("");

    var more=monitorState.hasMore&&!feedFilter&&feedSource!=="spoken"
      ? '<div class="nt-signals-more">'+btn("outline","sm","Load more mentions",' data-next-offset="'+esc(String(monitorState.nextOffset))
        +'" data-term="'+esc(term)+'"',"mention-more")+"</div>"
      : "";
    app.innerHTML=mentionsShell(head,'<div class="nt-signals-groups mgroups">'+html+"</div>",more+pickBarHtml("mentions"));
    initMentionPicks();
    applyMentionPicks();
    setTimeout(reportSize,60);
  }

  /** Whichever mention screen the data supports — merged when both answered. */
  function renderMentions(){
    if(feedIsMerged())return renderFeed();
    if(lastMentionKind==="spoken")return renderSpoken();
    return renderMonitor();
  }

  // The source toggle, the merged feed's platform chips and its select-all.
  // Distinct data attributes from either single screen's, so a merged view
  // cannot be driven by a handler that reads the other's state.
  document.addEventListener("click",function(e){
    if(!e.target.closest)return;
    var src=e.target.closest("[data-source]");
    if(src&&feedIsMerged()){
      feedSource=src.getAttribute("data-source")||"both";
      // A filter that survives into a source with nothing on that network is
      // a dead end the reader did not ask for.
      if(feedFilter&&!feedCounts()[feedFilter])feedFilter="";
      renderFeed();
      return;
    }
    var chip=e.target.closest("[data-feed-filter]");
    if(chip&&feedIsMerged()){
      if(chip.hasAttribute("disabled"))return;
      feedFilter=chip.getAttribute("data-feed-filter")||"";
      renderFeed();
      return;
    }
    var rest=e.target.closest("[data-expand]");
    if(rest&&feedIsMerged()){
      var rk=rest.getAttribute("data-expand")||"";
      expandedGroups[rk]=!expandedGroups[rk];
      renderFeed();
      return;
    }
    var all=e.target.closest("[data-feed-all]");
    if(all&&feedIsMerged()){
      var key=all.getAttribute("data-feed-all")||"";
      var group=null;
      mergedGroups().forEach(function(g){if(g.key===key)group=g;});
      if(!group)return;
      var ids=[];
      group.spoken.forEach(function(h){
        (h.excerpts||[]).forEach(function(ex,i){ids.push(spokenId(h,ex,i));});
      });
      group.typed.forEach(function(m){if(m.id)ids.push(String(m.id));});
      var turnOn=ids.some(function(id){return pickedMentions.indexOf(id)<0;});
      ids.forEach(function(id){
        var i=pickedMentions.indexOf(id);
        if(turnOn&&i<0)pickedMentions.push(id);
        if(!turnOn&&i>=0)pickedMentions.splice(i,1);
      });
      applyMentionPicks();
    }
  });

  /**
   * Make what is on screen agree with the selection — after a redraw, and
   * after a select-all that reached comments no row is showing.
   */
  function applyMentionPicks(){
    document.querySelectorAll(".mention-pick").forEach(function(b){
      var on=pickedMentions.indexOf(b.getAttribute("data-mid")||"")>=0;
      b.checked=on;
      var row=b.closest(".mention");
      if(row){row.classList.toggle("picked",on);row.classList.toggle("is-picked",on);}
    });
    document.querySelectorAll("[data-group-all]").forEach(function(b){
      var t=groupByKey(b.getAttribute("data-group-all")||"");
      if(!t)return;
      var ids=selectableMentions(t).map(function(m){return String(m.id||"");}).filter(Boolean);
      var allOn=ids.length&&ids.every(function(id){return pickedMentions.indexOf(id)>=0;});
      b.textContent=allOn?"Clear these":"Select all "+ids.length;
    });
    if(feedIsMerged()){
      var byKey={};
      mergedGroups().forEach(function(g){byKey[g.key]=g;});
      document.querySelectorAll("[data-feed-all]").forEach(function(b){
        var g=byKey[b.getAttribute("data-feed-all")||""];
        if(!g)return;
        var ids=[];
        g.spoken.forEach(function(h){
          (h.excerpts||[]).forEach(function(ex,i){ids.push(spokenId(h,ex,i));});
        });
        g.typed.forEach(function(m){if(m.id)ids.push(String(m.id));});
        var on=ids.length&&ids.every(function(id){return pickedMentions.indexOf(id)>=0;});
        b.textContent=on?"Clear these":"Select all "+ids.length;
      });
    }
    syncMentionBar();
  }

  /**
   * Show where the term actually appears in a comment.
   *
   * Walked by index rather than matched by regex: this template is embedded in
   * a Rust raw string as well as a TS literal, and a backslash means different
   * things in the two — so the file carries none at all. Escaping each slice
   * separately also means the mark cannot be injected by the comment text,
   * every word of which came from a stranger.
   */
  function highlightTerm(text,term){
    var src=String(text||""),t=String(term||"").trim();
    if(!t)return esc(src);
    var low=src.toLowerCase(),needle=t.toLowerCase(),out="",i=0;
    for(;;){
      var at=low.indexOf(needle,i);
      if(at<0){out+=esc(src.slice(i));break;}
      out+=esc(src.slice(i,at))+"<mark>"+esc(src.slice(at,at+needle.length))+"</mark>";
      i=at+needle.length;
    }
    return out;
  }

  /**
   * The time the way someone would say it. A monitoring feed is read for
   * recency above all — "today at 7:25 PM" answers the question the reader
   * actually has, which "2026-09-01T19:25:04Z" does not.
   */
  function friendlyTime(v){
    var s=String(v||"");
    if(!s)return "";
    var d=new Date(s);
    if(isNaN(d.getTime()))return s.slice(0,10);
    var now=new Date(),day=86400000;
    var clock=d.toLocaleTimeString([],{hour:"numeric",minute:"2-digit"});
    if(d.toDateString()===now.toDateString())return "today at "+clock;
    if(d.toDateString()===new Date(now.getTime()-day).toDateString())return "yesterday at "+clock;
    // Whole calendar days, not elapsed milliseconds. Flooring the elapsed
    // time reads 36 hours as one day, so a comment from the day before
    // yesterday printed "1 days ago" — wrong by a day and ungrammatical,
    // because the one-day case is already spelled "yesterday" above.
    var midnight=function(x){return new Date(x.getFullYear(),x.getMonth(),x.getDate()).getTime();};
    var days=Math.round((midnight(now)-midnight(d))/day);
    if(days>1&&days<7)return days+" days ago";
    var date=d.toLocaleDateString([],{month:"short",day:"numeric"});
    return d.getFullYear()===now.getFullYear()?date:date+", "+d.getFullYear();
  }

  function heartIcon(){
    return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21s-7.5-4.9-9.3-9A5.2 5.2 0 0 1 12 6.2 5.2 5.2 0 0 1 21.3 12c-1.8 4.1-9.3 9-9.3 9z"/></svg>';
  }
  function replyIcon(){
    return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M21 11.5a8.4 8.4 0 0 1-9 8.4 9.9 9.9 0 0 1-4.2-.9L3 20.5l1.6-4.6A8.2 8.2 0 0 1 3.6 11.5a8.4 8.4 0 0 1 9-8.4 8.4 8.4 0 0 1 8.4 8.4z"/></svg>';
  }

  /** First letter of a handle, for when the picture will not load. */
  function initialOf(name){
    var s=String(name||"").replace("@","").trim();
    return s?s.charAt(0).toUpperCase():"?";
  }

  /** "2026-08-18" rather than a full timestamp: the day is the useful part. */
  function shortDate(v){
    var s=String(v||"");
    if(!s)return "";
    var d=new Date(s);
    if(!isNaN(d.getTime()))return d.toISOString().slice(0,10);
    return s.slice(0,10);
  }

  /**
   * Selected comments, so an agent can be handed exactly the ones a person
   * picked — reply to these, escalate those. The ids come straight from the
   * tool result, so what the host receives addresses the same comments.
   */
  var pickedMentions=[];
  var mentionPicksWired=false;
  // Idempotent: the monitoring screen redraws on every filter and sort, and a
  // listener added per redraw would fire a selection several times over.
  function initMentionPicks(){
    if(!mentionPicksWired){
      mentionPicksWired=true;
      document.addEventListener("change",onMentionPick);
      document.addEventListener("click",function(e){
        var c=e.target.closest&&e.target.closest("#pickclear");
        if(!c||!pickedMentions.length)return;
        pickedMentions=[];
        applyMentionPicks();
      },true);
    }
    syncMentionBar();
  }
  function onMentionPick(e){
    var box=e.target;
    if(!box||!box.classList||!box.classList.contains("mention-pick"))return;
    var id=box.getAttribute("data-mid")||"";
    var i=pickedMentions.indexOf(id);
    if(box.checked&&i<0)pickedMentions.push(id);
    if(!box.checked&&i>=0)pickedMentions.splice(i,1);
    var row=box.closest(".mention");
    if(row){row.classList.toggle("picked",box.checked);row.classList.toggle("is-picked",box.checked);}
    syncMentionBar();
  }
  function syncMentionBar(){
    var bar=document.getElementById("pickbar");
    if(!bar)return;
    var n=document.getElementById("pickn");
    if(pickedMentions.length){
      bar.hidden=false;
      if(n)n.textContent=pickedMentions.length;
      var hint=document.getElementById("pickhint");
      if(hint){
        var spoken=0;
        pickedMentions.forEach(function(id){if(id.indexOf("spoken:")===0)spoken++;});
        var typed=pickedMentions.length-spoken;
        // Which posts the picks came from is the thing that decides whether
        // "Analyse these" can run (analyze_comments reads one post), so the
        // hint says it before the button has to refuse.
        var posts={};
        (monitorState?monitorState.threads:[]).forEach(function(t){
          (t.mentions||[]).forEach(function(m){
            if(pickedMentions.indexOf(String(m.id||""))>=0)posts[groupKey(t)]=true;
          });
        });
        var nPosts=Object.keys(posts).length;
        hint.textContent=spoken
          ? spoken+" spoken, "+typed+" typed"
          : nPosts>1?"from "+nPosts+" posts":"from 1 post";
      }
      var go=document.getElementById("pickgo");
      if(go){go.disabled=false;setGoLabel(go,"Analyse these");}
    }else{
      bar.hidden=true;
    }
    setTimeout(reportSize,60);
  }

  // Selected comments go to the host as a tool call. analyze_comments's own
  // inputSchema is {url, limit?}.strict() — one post, not an arbitrary
  // hand-picked set of texts/ids — so this used to post {comments, ids}
  // regardless of how many posts the selection spanned, and a real host
  // executing that call got a schema rejection every time; the "Try in
  // chat"/timeout fallback was the only thing anyone ever saw work. Now:
  // find which post(s) the picks belong to, and if they are all the same
  // one, ask analyze_comments to re-read that post's comments (the nearest
  // thing to "analyse these" the tool can actually do); otherwise say why
  // not, rather than sending a call the schema will refuse.
  document.addEventListener("click",function(e){
    var go=e.target.closest&&e.target.closest("#pickgo");
    if(!go||!pickedMentions.length)return;
    if(!document.querySelector(".mention-pick"))return; // the compare bar owns it
    e.stopPropagation();
    var urls={};
    (monitorState?monitorState.threads:[]).forEach(function(t){
      var u=t.post&&(t.post.externalUrl||t.post.url);
      if(!u)return;
      (t.mentions||[]).forEach(function(m){
        if(pickedMentions.indexOf(String(m.id||""))>=0)urls[u]=true;
      });
    });
    // A spoken pick is a line from a transcript, not a comment with an id
    // analyze_comments could re-read. Re-reading its post's comments would
    // answer a different question from the one that was asked, so say so
    // rather than quietly analysing something else.
    var spokenPicks=0;
    pickedMentions.forEach(function(id){if(id.indexOf("spoken:")===0)spokenPicks++;});
    var distinct=Object.keys(urls);
    // Why not is said in the bar's own hint, where the eye already is, and
    // the button keeps its label: a button that renames itself to explain a
    // refusal reads as a different action.
    if(spokenPicks||distinct.length!==1){
      var hint=document.getElementById("pickhint");
      var why=spokenPicks?"Spoken lines are not comments"
        :distinct.length===0?"Couldn’t find that post":"Pick comments from one post only";
      if(hint){hint.textContent=why;setTimeout(syncMentionBar,2200);}
      return;
    }
    go.disabled=true;setGoLabel(go,"Sending…");
    // The answer is drawn here, as Read comments draws it: a host that runs
    // a view's call hands the result back to the view and nowhere else, so a
    // "Sent" that dropped it left a paid read with nothing on screen.
    invokeTool("analyze_comments",{url:distinct[0],limit:Math.max(pickedMentions.length,20)},function(r){
      if(renderToolResult(r))return;
      setGoLabel(go,"Sent");
      setTimeout(function(){go.disabled=false;setGoLabel(go,"Analyse these");},1800);
    },function(reason){
      if(reason){go.disabled=false;setGoLabel(go,"Analyse these");sayCallFailed(go,reason);return;}
      setGoLabel(go,"Try in chat");
      setTimeout(function(){go.disabled=false;setGoLabel(go,"Analyse these");},1800);
    });
  },true);

  // Load more asks the host to re-run the tool with the next offset, which is
  // the only way a sandboxed view can page: it has no data of its own. The
  // page comes back to this view alone, so it is appended here - "Loaded ✓"
  // over an unchanged list was a charged page nobody could see. Totals and
  // per-network counts already describe the whole sweep; only the threads
  // and where the next page starts are the page's own.
  document.addEventListener("click",function(e){
    var b=e.target.closest&&e.target.closest(".mention-more");
    if(!b||b.disabled)return;
    b.disabled=true;
    var was=b.textContent;
    b.textContent="Loading…";
    invokeTool("search_mentions",{
      term:b.getAttribute("data-term")||"",
      offset:Number(b.getAttribute("data-next-offset")||0),
    },function(r){
      var sc=r&&r.structuredContent;
      if(!sc||!Array.isArray(sc.threads)||!monitorState||String(sc.term||"")!==monitorState.term){
        b.textContent="Loaded ✓";return;
      }
      // Keep the bookkeeping renderToolResult keeps, so a host that also
      // pushes this page as a tool-result does not redraw it as the whole list.
      lastOutRef=sc;
      try{ lastOutSig=JSON.stringify(sc); }catch(err){ lastOutSig=""; }
      toolResultReceived=true;
      monitorState.threads=monitorState.threads.concat(sc.threads);
      monitorState.hasMore=!!sc.hasMore;
      monitorState.nextOffset=sc.nextOffset;
      renderMentions();
      setTimeout(reportSize,60);
    },function(reason){
      b.disabled=false;b.textContent=was;
      if(reason)sayCallFailed(b,reason);
    });
  });

